def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import subprocess
    import sys

    def get_interpreter_from_shebang(script_path: str) -> str:
        try:
            with open(script_path, 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    shebang_args = first_line[2:].split()
                    interpreter = shebang_args[0]
                    if os.path.exists(interpreter):
                        return interpreter
        except Exception as e:
            print(f"Error reading shebang from {script_path}: {e}", file=sys.stderr)
        return sys.executable

    if not cmd:
        return cmd

    script_path = cmd[0]
    if os.name == 'nt':
        if not os.path.splitext(script_path)[1]:
            script_path += '.py'
        interpreter = get_interpreter_from_shebang(script_path)
        return (interpreter, script_path, *cmd[1:])
    return cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    if not sys.platform.startswith('win'):
        return cmd

    def has_shebang(first_line: str) -> bool:
        return first_line.startswith('#!')

    def get_interpreter(first_line: str) -> str:
        parts = first_line.split()
        if len(parts) > 1:
            return parts[1].strip()
        return ''

    if cmd:
        script_path = cmd[0]
        if os.path.isfile(script_path):
            with open(script_path, 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if has_shebang(first_line):
                    interpreter = get_interpreter(first_line)
                    if interpreter:
                        # Check if the interpreter is a path to a python executable
                        if 'python' in os.path.basename(interpreter).lower():
                            # Prepend the interpreter to the command
                            return (interpreter,) + cmd
    return cmd

