    if not orderings:
        return []

    # Create a graph where each element points to its successor
    graph = {}
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            current = ordering[i]
            next_item = ordering[i + 1]
            if current in graph:
                graph[current].append(next_item)
            else:
                graph[current] = [next_item]

    # Find all elements with no incoming edges (starting points)
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] = in_degree.get(neighbor, 0) + 1

    # Initialize the result list and queue with nodes having zero in-degree
    result = []
    queue = [node for node in in_degree if in_degree[node] == 0]

    while queue:
        # Process nodes with zero in-degree
        queue.sort(reverse=True)  # To maintain a consistent order
        current = queue.pop()
        result.append(current)

        if current in graph:
            for neighbor in graph[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

    # Check for cycles
    if len(result) != len(in_degree):
        raise ValueError("Cycle detected in orderings")

    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    try:
        merged = []
        position_map = {}

        for ordering in orderings:
            for index, item in enumerate(ordering):
                if item not in position_map:
                    position_map[item] = []
                position_map[item].append((len(merged), index))

        orderings.sort(key=lambda o: next((pos for pos, _ in position_map[o[0]]), float('inf')))

        for ordering in orderings:
            last_added = None
            for item in ordering:
                if item not in merged:
                    if last_added is None:
                        merged.append(item)
                    else:
                        merged.insert(next((i for i, x in enumerate(merged) if x == last_added), len(merged)) + 1, item)
                last_added = item

        return merged

    except Exception as e:
        print(f"An error occurred: {e}")
        return []

