def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if not any(issubclass(c, cls) for c in minimal):
            minimal.append(cls)
        else:
            minimal = [c for c in minimal if not issubclass(cls, c)]
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not all(isinstance(cls, type) for cls in classes):
        raise TypeError("All elements in the list must be types.")

    minimal = []
    for cls in classes:
        if not any(issubclass(cls, base) and cls is not base for base in minimal):
            minimal.append(cls)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimized = []
    for cls in classes:
        if cls not in seen:
            minimized.append(cls)
            seen.add(cls)
            seen.update(cls.__mro__[1:])  # Exclude the class itself to avoid duplicates
    return minimized

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    def is_parent(base, cls):
        return issubclass(cls, base) and base is not cls

    minimal = []
    for cls in classes:
        if any(is_parent(base, cls) for base in minimal):
            continue
        minimal = [base for base in minimal if not is_parent(cls, base)]
        minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def issubclass_helper(child, parent):
        # Custom issubclass to handle cases where direct subclassing might not be in MRO
        return any(parent in cls.__mro__ for cls in child.__mro__)

    seen = set()
    result = []

    for cls in classes:
        if cls in seen:
            continue
        # Check if this class is a subclass of any other class in the list
        if any(issubclass_helper(cls, other) for other in classes if other is not cls):
            continue
        result.append(cls)
        seen.add(cls)
        # Remove any subclass of this class from the result
        result = [other for other in result if not issubclass_helper(other, cls)]

    return result

