    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if not isinstance(sequence, (tuple, list)):
        sequence = (sequence,)

    for item in sequence:
        if isinstance(item, tuple):
            _normalizeargs(item, output)
        elif hasattr(item, '__provides__') and hasattr(item, '__class__'):
            cls = item.__class__
            if hasattr(cls, '__bases__') and InterfaceClass in cls.__mro__:
                output.append(item)
            elif hasattr(cls, '__mro__') and zope.interface.declarations.Implements in cls.__mro__:
                output.append(item)
        else:
            raise ValueError("Invalid item in sequence: {}".format(item))

    return output

