            'error_t_low': 'y_low',
            # Add more mappings as necessary
        }

        for error_key, context_key in error_mapping.items():
            if hasattr(self, error_key):
                error_index = getattr(self, error_key)
                if context_key not in context.error:
                    context.error[context_key] = {'index': error_index}

