    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if not seq:
        return False

    def is_fill_request(element):
        return isinstance(element, FillRequest)

    def contains_fill_request(sequence):
        return any(is_fill_request(item) for item in sequence)

    def is_source_sequence(sequence):
        return isinstance(sequence, Source)

    if is_fill_request(seq):
        return True

    if isinstance(seq, (list, tuple)):
        if contains_fill_request(seq) and not is_source_sequence(seq):
            return True

    return False

