            return True

        # Check if seq is a sequence and contains at least one FillRequest
        if isinstance(seq, Sequence) and not isinstance(seq, Source):
            return any(isinstance(item, FillRequest) and not isinstance(item, Source) for item in seq)

        return False
    except Exception:
        return False

