def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _difference_recursive(sub_d1, sub_d2, current_level):
        if level >= 0 and current_level > level:
            return sub_d1.copy()

        diff = {}
        for key in sub_d1:
            if key not in sub_d2:
                diff[key] = sub_d1[key]
            elif isinstance(sub_d1[key], dict) and isinstance(sub_d2[key], dict):
                sub_diff = _difference_recursive(sub_d1[key], sub_d2[key], current_level + 1)
                if sub_diff:
                    diff[key] = sub_diff
            elif sub_d1[key] != sub_d2[key]:
                diff[key] = sub_d1[key]
        return diff

    if not isinstance(d1, dict):
        raise ValueError("d1 must be a dictionary.")
    if not isinstance(d2, dict):
        raise ValueError("d2 must be a dictionary.")

    return _difference_recursive(d1, d2, 0)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("coord must be a 2-dimensional tuple")

    if not (self.edges_x[0] <= coord[0] <= self.edges_x[-1] and self.edges_y[0] <= coord[1] <= self.edges_y[-1]):
        return  # Ignore coordinates outside the histogram edges

    bin_x = np.searchsorted(self.edges_x, coord[0], side='right') - 1
    bin_y = np.searchsorted(self.edges_y, coord[1], side='right') - 1

    if 0 <= bin_x < len(self.values) and 0 <= bin_y < len(self.values[0]):
        self.values[bin_x, bin_y] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (self.edges[0] <= coord < self.edges[-1]):
        return

    index = np.searchsorted(self.edges, coord) - 1
    if index >= 0 and index < len(self.values):
        self.values[index] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != len(self.edges) - 1:
        raise ValueError("coord must be a tuple with the same dimension as the number of edges minus one")

    for i, (x, edge) in enumerate(zip(coord, self.edges)):
        if x < edge[0] or x >= edge[-1]:
            return  # Ignore coordinates outside the histogram edges

    indices = [np.searchsorted(edge, x, side='right') - 1 for x, edge in zip(coord, self.edges)]
    self.values[tuple(indices)] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != len(self.edges) - 1:
        raise ValueError("coord must be a tuple with the same dimensionality as the histogram edges minus one.")

    indices = []
    for i, (edge, c) in enumerate(zip(self.edges, coord)):
        idx = np.searchsorted(edge, c, side='right') - 1
        if idx < 0 or idx >= len(edge) - 1:
            return  # coordinate is outside the histogram edges
        indices.append(idx)

    self.values[tuple(indices)] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    key_regex = re.compile(r'^[a-zA-Z0-9-_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9-_]+$')
    errors = []

    def check_key(key):
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '[a-zA-Z0-9-_]+'"])

    def check_value(value, key):
        if isinstance(value, list):
            for v in value:
                check_value(v, key)
        elif not isinstance(value, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif not value_regex.match(value):
            errors.append({key: f"Label value '{value}' for key '{key}' does not match the regex '[a-zA-Z0-9-_]+'"])

    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'expected a dictionary'}])

    for key, value in labels.items():
        check_key(key)
        check_value(value, key)

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from collections.abc import Iterable

    key_regex = re.compile(r"^[a-zA-Z0-9_]+$")
    value_regex = re.compile(r"^[a-zA-Z0-9_]+$")

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str) or not key_regex.match(key):
            errors.append({str(key): f"Label key '{key}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        # Validate value
        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9_]+$'"})
        elif not isinstance(value, Iterable) or isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            for v in value:
                if not isinstance(v, str) or not value_regex.match(v):
                    errors.append({str(v): f"Label value '{v}' does not match the regex '^[a-zA-Z0-9_]+$'"})


    if errors:
        raise ValidationError(messages=errors)

class ValidationError(Exception):
    def __init__(self, messages):
        self.messages = messages
        super().__init__(str(messages))

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    identifying_fields = {'apiVersion', 'kind', 'metadata'}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    return observer_schema

