            default observer schema
    """
    if not app or not app.spec or not app.spec.manifest:
        return

    default_schema = {
        "observers": {}
    }

    for resource in app.spec.manifest:
        resource_key = f"{resource['apiVersion']}/{resource['kind']}"
        if resource_key not in app.spec.observers:
            default_schema["observers"][resource_key] = {
                "kind": "observer.kubernetes",
                "spec": {
                    "apiVersion": resource["apiVersion"],
                    "kind": resource["kind"],
                    "name": resource["metadata"].get("name"),
                    "namespace": resource["metadata"].get("namespace"),
                    "watch_events": ["ADDED", "MODIFIED", "DELETED"]
                }
            }

    if not app.spec.observers:
        app.spec.observers = default_schema["observers"]
    else:
        app.spec.observers.update(default_schema["observers"])

