            default observer schema
    """
    default_schema = {}
    try:
        for resource in app.spec.manifest:
            resource_kind = resource.get('kind')
            if resource_kind and resource_kind not in app.spec.observers:
                default_schema[resource_kind] = {
                    'type': 'object',
                    'properties': {
