                            'type': 'object'
                        }
                    }
                }
    except AttributeError as e:
        # Handle the case where app or app.spec is None
        raise ValueError("Invalid application or application spec provided") from e
    except KeyError as e:
        # Handle the case where a required key is missing in the resource
        raise ValueError(f"Missing required key in resource: {e}") from e
    except Exception as e:
        # Catch any other exceptions that may occur
        raise RuntimeError("An error occurred while generating the default observer schema") from e

    return default_schema

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    import re
    from collections.abc import Iterable, Mapping, Sequence

    # Check if the in_style is named or ordinal
    in_style = self.SQLParams.in_style
    out_style = self.SQLParams.out_style

    if isinstance(many_params, Sequence) and not isinstance(many_params, (str, bytes)):
        params_are_sequences = all(isinstance(param, Sequence) and not isinstance(param, Mapping) for param in many_params)
        params_are_mappings = all(isinstance(param, Mapping) for param in many_params)
    else:
        raise ValueError("many_params must be an iterable of sequences or mappings")

    if in_style == 'named' and not params_are_mappings:
        raise ValueError("For named parameters, each set of parameters must be a mapping.")

    if in_style == 'ordinal' and not params_are_sequences:
        raise ValueError("For ordinal parameters, each set of parameters must be a sequence.")

    # Define patterns and replacements based on in_style and out_style
    if in_style == 'named':
        if out_style == 'qmark':
            pattern = re.compile(r':(\w+)')
            replacement = '?'
        elif out_style == 'numeric':
            pattern = re.compile(r':(\w+)')
            replacement = lambda m: f':{self._param_index[m.group(1)]}'
        elif out_style == 'named':
            pattern = re.compile(r':(\w+)')
            replacement = lambda m: f':param_{m.group(1)}'
        elif out_style == 'pyformat':
            pattern = re.compile(r':(\w+)')
            replacement = r'%(\g<1>)s'
        elif out_style == 'format':
            pattern = re.compile(r':(\w+)')
            replacement = '{}'
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

        # Create a dictionary to keep track of the order of named parameters
        self._param_index = {}
        param_count = 1
        for params in many_params:
            for key in params:
                if key not in self._param_index:
                    self._param_index[key] = param_count
                    param_count += 1

    elif in_style == 'ordinal':
        if out_style == 'qmark':
            pattern = re.compile(r'\?')
            replacement = '?'
        elif out_style == 'numeric':
            pattern = re.compile(r'\?')
            replacement = lambda m: f':{self._param_index}'
        elif out_style == 'named':
            pattern = re.compile(r'\?')
            replacement = lambda m: f':param_{self._param_index}'
        elif out_style == 'pyformat':
            pattern = re.compile(r'\?')
            replacement = lambda m: f'%({self._param_index})s'
        elif out_style == 'format':
            pattern = re.compile(r'\?')
            replacement = '{}'
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

        # Initialize the param_index for ordinal parameters
        self._param_index = 1

    else:
        raise ValueError(f"Unsupported in-style: {in_style}")

    # Format the SQL query
    if isinstance(replacement, str):
        formatted_sql = pattern.sub(replacement, sql)
    else:
        formatted_sql = pattern.sub(replacement, sql)

    # Convert the parameters to out-style
    if out_style == 'named' and in_style == 'named':
        out_style_params = [{f'param_{key}': value for key, value in params.items()} for params in many_params]
    elif out_style == 'numeric':
        out_style_params = [[params[key] for key in sorted(params)] for params in many_params]
    else:
        out_style_params = many_params

    return formatted_sql, out_style_params

