    elif in_style in ('qmark', 'format'):
        param_pattern = r'\?'
        param_replacer = '?'
        param_dict = lambda match: len(match.group(0))
    elif in_style == 'numeric':
        param_pattern = r':(\d+)'
        param_replacer = '?'
        param_dict = lambda match: int(match.group(1)) - 1
    else:
        raise ValueError(f"Unsupported in-style parameter: {in_style}")

    converted_sql = re.sub(param_pattern, param_replacer, sql)
    converted_params = []

    for params in many_params:
        if in_style in ('named', 'pyformat'):
            if not isinstance(params, Mapping):
