            if not isinstance(params, Sequence):
                raise TypeError("params must be a Sequence if in_style is qmark, format, or numeric")
        else:
            raise ValueError(f"Unsupported in-style parameter: {in_style}")

        if out_style == 'named':
            converted_params.append(dict(params))
        elif out_style == 'pyformat':
            converted_params.append({f"%({k})s": v for k, v in params.items()})
        elif out_style == 'qmark':
            converted_params.append([params[i] for i in range(len(params))])
        elif out_style == 'format':
            converted_params.append([params[i] for i in range(len(params))])
        elif out_style == 'numeric':
            converted_params.append([params[i] for i in range(len(params))])
        else:
            raise ValueError(f"Unsupported out-style parameter: {out_style}")

    return converted_sql, converted_params

