def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Source path or zipfile object
    xmls : list of str
        XML filenames
    files : list of str
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: list of files associated with the XML
    """
    import os
    from zipfile import ZipFile

    grouped_files = {xml: [] for xml in xmls}

    if isinstance(source, ZipFile):
        for file in files:
            xml_basename = os.path.splitext(os.path.basename(file))[0]
            for xml in xmls:
                if os.path.splitext(os.path.basename(xml))[0] == xml_basename:
                    grouped_files[xml].append(file)
    else:
        for file in files:
            xml_basename = os.path.splitext(os.path.basename(file))[0]
            for xml in xmls:
                if os.path.splitext(os.path.basename(xml))[0] == xml_basename:
                    grouped_files[xml].append(file)

    # Remove XML files from the groups if they are present in the files list
    for xml in xmls:
        if xml in grouped_files[xml]:
            grouped_files[xml].remove(xml)

    # Remove empty entries from the dictionary
    grouped_files = {k: v for k, v in grouped_files.items() if v}

    return grouped_files

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str) or not os.path.isdir(folder):
        raise ValueError("Provided folder path is not valid or not a directory")

    package_data = {}

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                xml_basename = os.path.splitext(file)[0]

                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()

                    if xml_basename not in package_data:
                        package_data[xml_basename] = []

                    package_data[xml_basename].append({
                        'file_path': file_path,
                        'xml_content': ET.tostring(root_element, encoding='unicode')
                    })

                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}")
                except Exception as e:
                    print(f"Warning: An error occurred while processing {file_path}: {e}")

    return package_data

