def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = []
    if debug:
        parts.append("{}<{} object at {}>".format(indent_str, self.__class__.__name__, hex(id(self))))
    else:
        parts.append("{}{}".format(indent_str, self.__class__.__name__))
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple, set)):
            parts.append("{}  {}:".format(indent_str, key))
            for item in value:
                parts.append("{}    {}".format(indent_str, self._pretty_repr(item, indent + 4)))
        else:
            parts.append("{}  {}: {}".format(indent_str, key, self._pretty_repr(value, indent + 2)))
    return '\n'.join(parts)

def _pretty_repr(self, value, indent):
    indent_str = ' ' * indent
    if isinstance(value, (list, tuple, set)):
        return "[\n{}{}\n{}]".format(
            ('\n' + indent_str).join(self._pretty_repr(item, indent + 2) for item in value),
            indent_str, indent_str[:-2]
        )
    elif isinstance(value, dict):
        return "{{\n{}{}\n{}}}".format(
            ('\n' + indent_str).join("{}: {}".format(k, self._pretty_repr(v, indent + 2)) for k, v in value.items()),
            indent_str, indent_str[:-2]
        )
    elif hasattr(value, 'pretty'):
        return value.pretty(indent)
    else:
        return str(value)

