    return '\n'.join(result)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op, a, b = expr
        if op == '&':
            if b[0] == '|' and b[1] == a:
                return a
            if b[0] == '|' and b[2] == a:
                return a
            if b[0] == '|' and b[1][0] == '~' and b[1][1] == a:
                return ('&', a, b[2])
            if b[0] == '|' and b[2][0] == '~' and b[2][1] == a:
                return ('&', a, b[1])
        elif op == '|':
            if b[0] == '&' and b[1] == a:
                return a
            if b[0] == '&' and b[2] == a:
                return a
            if b[0] == '&' and b[1][0] == '~' and b[1][1] == a:
                return ('|', a, b[2])
            if b[0] == '&' and b[2][0] == '~' and b[2][1] == a:
                return ('|', a, b[1])
        return expr

    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    return [apply_absorption(arg) for arg in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not args or len(args) < 3:
        raise ValueError("args must contain at least three elements: operand, operator, and operand.")

    operand1, operator, operand2 = args[:3]
    new_args = args[3:]

    if operator == '&':
        if operand2 == f"({operand1} | _)":
            return [operand1] + new_args
        elif operand2 == f"(~{operand1} | _)":
            return [f"{operand1} & _"] + new_args
    elif operator == '|':
        if operand2 == f"({operand1} & _)":
            return [operand1] + new_args
        elif operand2 == f"(~{operand1} & _)":
            return [f"{operand1} | _"] + new_args

    return [operand1, operator, operand2] + new_args

