        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            op, left, right = expr
            if op == '&':
                if right == ('|', left, 'B'):
                    return left
                if right == ('|', '~', left, 'B'):
                    return ('&', left, 'B')
            elif op == '|':
                if right == ('&', left, 'B'):
                    return left
                if right == ('&', '~', left, 'B'):
                    return ('|', left, 'B')
            return (op, apply_absorption(left), apply_absorption(right))
        return expr

    return [apply_absorption(arg) for arg in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify_expression(expr):
        if isinstance(expr, tuple):
            op, *sub_exprs = expr
            if op == '&':
                simplified_subs = [simplify_expression(sub) for sub in sub_exprs]
                for i, sub in enumerate(simplified_subs):
                    if isinstance(sub, tuple) and sub[0] == '|':
                        left, right = sub[1], sub[2]
                        if simplified_subs[i - 1] == left or simplified_subs[i - 1] == right:
                            return simplified_subs[i - 1]
                        if isinstance(left, tuple) and left[0] == '~' and left[1] == simplified_subs[i - 1]:
                            return ('&', simplified_subs[i - 1], right)
                        if isinstance(right, tuple) and right[0] == '~' and right[1] == simplified_subs[i - 1]:
                            return ('&', simplified_subs[i - 1], left)
                return ('&', *simplified_subs)
            elif op == '|':
                simplified_subs = [simplify_expression(sub) for sub in sub_exprs]
                for i, sub in enumerate(simplified_subs):
                    if isinstance(sub, tuple) and sub[0] == '&':
                        left, right = sub[1], sub[2]
                        if simplified_subs[i - 1] == left or simplified_subs[i - 1] == right:
                            return simplified_subs[i - 1]
                        if isinstance(left, tuple) and left[0] == '~' and left[1] == simplified_subs[i - 1]:
                            return ('|', simplified_subs[i - 1], right)
                        if isinstance(right, tuple) and right[0] == '~' and right[1] == simplified_subs[i - 1]:
                            return ('|', simplified_subs[i - 1], left)
                return ('|', *simplified_subs)
        return expr

    return [simplify_expression(arg) for arg in args]

