        raise ValueError("env must be a dict or None")

    full_command = commands + args
    stdout = subprocess.PIPE
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        process = subprocess.Popen(full_command, cwd=cwd, env=env if env else os.environ, stdout=stdout, stderr=stderr)
        output, error = process.communicate()
        if process.returncode != 0:
            error_message = error.decode() if error else "Command failed with return code {}".format(process.returncode)
            raise subprocess.CalledProcessError(returncode=process.returncode, cmd=full_command, output=output, stderr=error)
        if verbose:
