def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'

        if not os.path.isdir(path):
            return 'other: path is not a file or directory'

        namaste_files = [f for f in os.listdir(path) if f.startswith('0=') and os.path.isfile(os.path.join(path, f))]

        if '0=ocfl' in namaste_files:
            return 'root'
        elif '0=ocfl_object' in namaste_files:
            return 'object'
        else:
            return 'other: no OCFL Namaste file found'

    except Exception as e:
        return f'other: error accessing path - {str(e)}'

