                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode

    def merge_values(existing_value, new_value):
        if isinstance(existing_value, MappingNode) and isinstance(new_value, MappingNode):
            existing_map = dict(existing_value.value)
            new_map = dict(new_value.value)
            merged_map = {**existing_map, **new_map}
            for key in existing_map:
                if key in new_map:
                    existing_map[key] = merge_values(existing_map[key], new_map[key])
            return MappingNode(tag=new_value.tag, value=list(existing_map.items()))
        else:
            return new_value

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            merged_dict[key] = merge_values(merged_dict[key], value_node)
        else:
            merged_dict[key] = value_node

    return list(merged_dict.items())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    def merge_mapping_nodes(node1, node2):
        if not isinstance(node1, ruamel.yaml.nodes.MappingNode) or not isinstance(node2, ruamel.yaml.nodes.MappingNode):
            raise ValueError("Both nodes must be MappingNode instances for merging.")

        merged_value = defaultdict(list)
        for key, value in node1.value + node2.value:
            merged_value[key].append(value)

        merged_items = []
        for key, values in merged_value.items():
            if all(isinstance(v, ruamel.yaml.nodes.MappingNode) for v in values):
                merged_value_node = ruamel.yaml.nodes.MappingNode(
                    tag='tag:yaml.org,2002:map',
                    value=[(k, merge_mapping_nodes(v1, v2)) for k, v1, v2 in zip(values[0].value.keys(), values[:-1], values[1:])],
                    start_mark=node1.start_mark,
                    end_mark=node1.end_mark
                )
                merged_items.append((key, merged_value_node))
            else:
                merged_items.append((key, values[-1]))

        return merged_items

    merged_dict = {}
    for key, value in nodes:
        if key.value in merged_dict:
            if isinstance(merged_dict[key.value], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged_dict[key.value].value = merge_mapping_nodes(merged_dict[key.value], value)
            else:
                merged_dict[key.value] = value
        else:
            merged_dict[key.value] = value

    return [(k, v) for k, v in merged_dict.items()]

