def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import subprocess

    def get_parser():
        from borgmatic.commands import all_arguments
        return all_arguments.build_parser()

    def format_command(parser, parent_command=''):
        commands = []
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for name, subparser in action.choices.items():
                    full_command = f'{parent_command} {name}'.strip()
                    commands.append(f"'{full_command}'")
                    commands.extend(format_command(subparser, full_command))
            else:
                if action.option_strings:
                    for option in action.option_strings:
                        commands.append(f"'{option}'")
        return commands

    def generate_completion_script(commands):
        script = [
            "_borgmatic() {",
            "    local cur prev opts",
            "    COMPREPLY=()",
            "    cur=\"${COMP_WORDS[COMP_CWORD]}\"",
            "    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"",
            "    opts='{}'".format(' '.join(commands)),
            "",
            "    COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )",
            "    return 0",
            "}",
            "",
            "complete -F _borgmatic borgmatic",
        ]
        return "\n".join(script)

    try:
        parser = get_parser()
        commands = format_command(parser)
        return generate_completion_script(commands)
    except Exception as e:
        print(f"An error occurred: {e}")
        return ""

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            namespace, args = parser.parse_known_args(unparsed_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = list(set(remaining_arguments) - set(args))
        except Exception as e:
            # Log or handle the exception as needed
            continue

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''

    parsed_namespaces = {}
    remaining_arguments = list(unparsed_arguments)

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(remaining_arguments)
            parsed_namespaces[name] = namespace
        except Exception as e:
            # If parsing fails, store an empty namespace
            parsed_namespaces[name] = argparse.Namespace()

    return parsed_namespaces, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::
            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Invalid size format")

    units = {'B': 1, 'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4, 'P': 1000**5}

    if size[-1].isalpha():
        numeric_part = size[:-1]
        unit = size[-1].upper()
    else:
        numeric_part = size
        unit = 'B'

    try:
        numeric_part = float(numeric_part)
    except ValueError:
        raise ValueError("Invalid numeric part in size")

    if unit not in units:
        raise ValueError("Invalid unit in size")

    return int(numeric_part * units[unit])

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements in the input iterable must be dictionaries.")
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

