def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not alphabet or not all(isinstance(c, str) for c in alphabet):
        raise ValueError("Alphabet must be a non-empty list of strings.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    result_str = ''.join(reversed(result))

    if padding is not None and len(result_str) < padding:
        result_str = alphabet[0] * (padding - len(result_str)) + result_str

    return result_str

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not alphabet or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must be a non-empty list of strings.")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two elements to form a valid base.")

    if number == 0:
        result = alphabet[0]
    else:
        result = []
        while number > 0:
            number, remainder = divmod(number, base)
            result.append(alphabet[remainder])
        result.reverse()

    result_str = ''.join(result)

    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("Padding must be a non-negative integer.")
        result_str = result_str.zfill(padding)

    return result_str

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters to form a valid numeral system.")

    if number == 0:
        result = alphabet[0]
    else:
        result = ''
        while number > 0:
            digit = number % base
            result = alphabet[digit] + result
            number //= base

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    base = len(alphabet)
    if number < 0:
        raise ValueError("Number must be non-negative.")
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None and len(digits) < padding:
        digits.extend(alphabet[0] * (padding - len(digits)))

    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("The number must be non-negative.")
    if not alphabet:
        raise ValueError("The alphabet list cannot be empty.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("The alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding or 1)

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    if padding:
        result.extend(alphabet[0] * (padding - len(result)))

    return ''.join(reversed(result))

