def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:
        # POSIX style splitting
        regex = r'(?:"([^"\\]*(?:\\.[^"\\]*)*)")|\'([^\']*)\'|([^\'"\s]+)'
    elif platform == 0:
        # Windows/CMD style splitting
        regex = r'(?:"([^"\\]*(?:\\.[^"\\]*)*)")|\'([^\']*)\'|([^\'"\s]+)'
    else:
        raise ValueError("Unsupported platform value")

    matches = re.findall(regex, s)
    return [item for match in matches for item in match if item]

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os
    import re

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:  # POSIX
        # Regex for POSIX command-line parsing
        return re.findall(r"""(?u)\G\s*(?:(['"])(?:(?=(\\?))\2.)*?\1|([^#\s]+))""", s)

    elif platform == 0:  # Windows/CMD
        # Regex for Windows CMD command-line parsing
        return re.findall(r"""(?u)\G\s*(?:(")(?:[^"]*"[^"]*"|\S*)|(\S+))""", s)

    else:
        raise ValueError("Unsupported platform value. Use 'this', 0, or 1.")

    return [match[0] or match[1] for match in matches if match[0] or match[1]]

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path
    import os

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive path {archive_path} does not exist.")

    tmp_path = Path(tmp_path)
    if not tmp_path.exists():
        tmp_path.mkdir(parents=True)

    if filename is None:
        filename = os.path.basename(archive_path).replace(".tar.gz", "").replace(".tar.bz2", "").replace(".zip", "")

    extract_path = tmp_path / filename
    if not extract_path.exists():
        extract_path.mkdir(parents=True)

    try:
        if archive_path.endswith(".tar.gz"):
            subprocess.run(["tar", "-xzf", archive_path, "-C", str(extract_path)], check=True)
        elif archive_path.endswith(".tar.bz2"):
            subprocess.run(["tar", "-xjf", archive_path, "-C", str(extract_path)], check=True)
        elif archive_path.endswith(".zip"):
            subprocess.run(["unzip", archive_path, "-d", str(extract_path)], check=True)
        else:
            raise ValueError(f"Unsupported archive format for {archive_path}")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}: {e}")

    return f"file://{extract_path.resolve()}"

