            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE if verbose else subprocess.DEVNULL,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.STDOUT,
            text=True
        )
        stdout, _ = process.communicate()
        if process.returncode != 0:
