def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import toml
    import yaml

    if overrides is None:
        overrides = {}

    configurations = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            if not os.path.exists(config_filename):
                log_records.append(logging.makeLogRecord({
                    'levelno': logging.ERROR,
                    'levelname': logging.getLevelName(logging.ERROR),
                    'name': 'config_loader',
                    'msg': f"Configuration file does not exist: {config_filename}"
                }))
                continue

            with open(config_filename, 'r') as file:
                if config_filename.endswith('.toml'):
                    config = toml.load(file)
                elif config_filename.endswith('.yaml') or config_filename.endswith('.yml'):
                    config = yaml.safe_load(file)
                else:
                    log_records.append(logging.makeLogRecord({
                        'levelno': logging.ERROR,
                        'levelname': logging.getLevelName(logging.ERROR),
                        'name': 'config_loader',
                        'msg': f"Unsupported file type for configuration: {config_filename}"
                    }))
                    continue

            if resolve_env:
                config = _resolve_environment_variables(config)

            configurations[config_filename] = {**config, **overrides}

        except Exception as e:
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': logging.getLevelName(logging.ERROR),
                'name': 'config_loader',
                'msg': f"Error parsing configuration file {config_filename}: {e}"
            }))

    return configurations, log_records

def _resolve_environment_variables(config):
    import os
    import re

    def getenv(match):
        env_var = match.group(1)
        default = match.group(2) if match.group(2) else ''
        return os.getenv(env_var, default)

    pattern = re.compile(r'\$\{([^}]+)(?::([^}]+))?\}')
    config_str = str(config)
    resolved_config_str = pattern.sub(getenv, config_str)
    return eval(resolved_config_str)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import json
    import logging.config

    parsed_configs = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(logging.LogRecord(name=__name__, level=logging.ERROR, pathname=filename, lineno=0,
                                                msg=f"Configuration file not found: {filename}", args=(), exc_info=None))
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except (json.JSONDecodeError, IOError) as e:
            log_records.append(logging.LogRecord(name=__name__, level=logging.ERROR, pathname=filename, lineno=0,
                                                msg=f"Error reading configuration file {filename}: {e}", args=(), exc_info=None))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        if overrides:
            config.update(overrides)

        parsed_configs[filename] = config

    return parsed_configs, log_records

