def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclass = None
    for base in bases:
        try:
            base_metaclass = type(base)
            if metaclass is None:
                metaclass = base_metaclass
            elif not issubclass(metaclass, base_metaclass):
                metaclass = type(f'__AnonymousMeta__', (base_metaclass, metaclass), {})
        except Exception as e:
            pass

    return metaclass or object

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclasses = set()

    # Collect metaclasses from bases
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)

    # Add explicit metaclass if provided
    if explicit_mc is not None:
        metaclasses.add(explicit_mc)

    # If there are multiple metaclasses, find a common base
    if len(metaclasses) > 1:
        common_base = type(object)
        for m in metaclasses:
            if issubclass(common_base, m):
                common_base = m
            elif not issubclass(m, common_base):
                raise TypeError("Metaclass conflict: bases have different metaclasses")
        return common_base

    # Return the single metaclass found
    return metaclasses.pop() if metaclasses else type(object)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        try:
            metaclass = type(base)
            if metaclass not in metaclasses:
                metaclasses.add(metaclass)
        except TypeError:
            continue

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common ancestor
    common_base = None
    for metaclass in metaclasses:
        if common_base is None:
            common_base = metaclass
        else:
            common_base = common_base.__mro__
            if metaclass not in common_base:
                for candidate in metaclass.__mro__:
                    if candidate in common_base:
                        common_base = candidate
                        break
            else:
                common_base = common_base[common_base.index(metaclass) + 1:]

            if common_base is None:
                raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

    return common_base

def determineMetaclass(bases, explicit_mc=None):
