    metaclasses = set()
    for base in bases:
        try:
            for baseobj in base.__mro__:
                metaclass = type(baseobj)
                if metaclass not in (type, object):
                    metaclasses.add(metaclass)
        except (AttributeError, TypeError):
            continue

    if not metaclasses:
