    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    matched_args = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when:
            condition_command = required_when.get('command')
            condition_arg = required_when.get('arg')
            condition_value = required_when.get('value')

            if condition_command and condition_command != command_name:
                continue

            if condition_arg and condition_value:
                if args.get(condition_arg) == condition_value:
                    matched_args.append(option.get('name'))

    return matched_args

