    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    # Assuming self.parsers is a dictionary of ArgumentParser objects
    if parser_name not in self.parsers:
        raise ValueError(f"No parser found for the command: {parser_name}")

    parser = self.parsers[parser_name]
    default_values = {action.dest: action.default for action in parser._actions}

    for arg, value in values_dict.items():
        if arg in default_values:
            try:
                # Convert to the type of the default value
                value_type = type(default_values[arg])
                if value_type == bool:
                    # Special handling for bool as argparse stores them as strings
                    values_dict[arg] = value.lower() in ['true', '1', 't', 'y', 'yes']
                else:
                    values_dict[arg] = value_type(value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Could not convert value for {arg}: {e}") from e
        else:
            # If the argument is not in the parser, remove it or handle as needed
            raise ValueError(f"Unknown argument: {arg}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    try:
        parser = getattr(self, parser_name)
    except AttributeError:
        raise ValueError(f"Parser '{parser_name}' not found in {self.__class__.__name__}")

    for arg_name, action in parser._actions:
        if arg_name not in values_dict:
            continue
        try:
            values_dict[arg_name] = action.type(values_dict[arg_name])
        except (ValueError, TypeError) as e:
            raise ValueError(f"Error converting {arg_name}: {str(e)}") from e

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        with open(spec_path, 'r') as file:
            plugin_spec = json.load(file)
        return flatten_dict(plugin_spec)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Error reading or parsing plugin spec: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

